script:
// Forgó mágneses mező – három, 120°-onként elhelyezett tekercs
// Rotating magnetic field – three coils placed 120° apart
//   i_k = Î·sin(ωt − k·120°)      B = B₁ + B₂ + B₃,  |B| = 1,5·B̂      n_s = 60·f / p

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#fbfbf8");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Forgó mágneses mező", en: "Rotating magnetic field"});
// Kezdő lassítás (a Sebesség csúszkán állítható) / Initial slow motion (change it on the Speed slider)
timeScale(0.002);
// A grafikon időablaka másodpercben / Chart time window in seconds
plotWindow(0.06);

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("f",  {hu: "Frekvencia f", en: "Frequency f"}, 1, 100, 50, 1, "Hz");
param("Im", {hu: "Áram csúcsértéke Î", en: "Peak current Î"}, 0, 20, 10, 0.1, "A");
param("p",  {hu: "Póluspárok száma p", en: "Pole pairs p"}, 1, 3, 1, 1, "");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("rev",   {hu: "Fázissorrend-csere (L2 ↔ L3)", en: "Swap phase order (L2 ↔ L3)"}, false);
toggle("loss",  {hu: "L3 fázis kiesése (egyfázisú üzem)", en: "Loss of phase L3 (single-phasing)"}, false);
toggle("parts", {hu: "Fázisonkénti mezővektorok (p = 1)", en: "Field vector of each phase (p = 1)"}, true);
toggle("trace", {hu: "A vektor végpontjának pályája", en: "Path of the vector tip"}, true);

const PH = [C.L1, C.L2, C.L3];
const sx = 320, sy = 320;   // állórész középpontja / stator centre
let th = 0;
const path = [];

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update(dt => { th += 2 * PI * P.f * dt; });

// Fázisáramok csúcsértéke és fázisa / peak and phase of each current
function currentPhasors() {
  if (P.loss) {   // L3 nélkül az 1. és 2. tekercs sorba kerül az U₁₂-re / coils 1 and 2 end up in series on U₁₂
    const a = P.Im * sqrt(3) / 2;
    return [[a, deg(30)], [a, deg(210)], [0, 0]];
  }
  return [[P.Im, 0], [P.Im, -deg(120)], [P.Im, -deg(240)]];
}

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const ph = currentPhasors();
  // A három áram pillanatértéke / instantaneous value of the three currents
  const i = ph.map(([a, phi]) => a * sin(th + phi));
  const axes = P.rev ? [0, deg(240), deg(120)] : [0, deg(120), deg(240)];   // tekercstengelyek / coil axes

  // Háromfázisú állórész; a vezetőkben ⊙/⊗ az áram iránya / Three-phase stator; ⊙/⊗ shows the current direction
  stator3(sx, sy, {p: P.p, i: i, imax: max(P.Im, 1e-9), axes: axes});
  circle(sx, sy, 160, {fill: "#ffffff", stroke: "#c3cad5", lw: 1.5, dash: [5, 5]});

  // Eredő mező = a három tekercs mezőjének vektori összege / resultant field = vector sum of the three coil fields
  const B = fieldVec(i, axes);           // villamos szög / electrical angle
  const k = 100 / max(P.Im, 1e-9);       // Î → 100 px, így 1,5·Î → 150 px
  if (P.parts && P.p === 1) {
    for (let j = 0; j < 3; j++) phasor(sx, sy, i[j] * k, axes[j], {stroke: PH[j], lw: 2}, "B" + "₁₂₃"[j]);
  }
  for (let m = 0; m < P.p; m++) {        // p póluspár: p mezőtengely / p pole pairs: p field axes
    phasor(sx, sy, B.mag * k, (B.angle + 2 * PI * m) / P.p, {stroke: C.red, lw: 4}, m === 0 ? "B" : "");
  }
  if (P.trace && B.mag > 1e-6) {
    const a = B.angle / P.p, tip = [sx + B.mag * k * cos(a), sy - B.mag * k * sin(a)];
    const lastPt = path[path.length - 1];
    if (!lastPt || hypot(tip[0] - lastPt[0], tip[1] - lastPt[1]) > 4) path.push(tip);   // térben mintavételezve / sampled in space
    if (path.length > 260) path.shift();
    polyline(path.concat([tip]), {stroke: C.red, lw: 1.5, alpha: 0.35});
  }
  circle(sx, sy, 5, {fill: C.ink});

  // Áramfázorok: a függőleges vetület a pillanatérték / current phasors: vertical projection = instantaneous value
  const px = 790, py = 215, R0 = 100;
  circle(px, py, R0, {stroke: C.light, lw: 1});
  line(px - 120, py, px + 120, py, {stroke: C.light, lw: 1});
  line(px, py - 120, px, py + 120, {stroke: C.light, lw: 1});
  ph.forEach(([a, phi], j) => {
    if (a < 1e-9) return;
    const L = a / max(P.Im, 1e-9) * R0, ang = th + phi;
    const tx = px + L * cos(ang), ty = py - L * sin(ang);
    line(tx, ty, px, ty, {stroke: PH[j], lw: 1, dash: [2, 4]});
    circle(px, ty, 4, {fill: PH[j]});
    phasor(px, py, L, ang, {stroke: PH[j], lw: 2.5}, "i" + "₁₂₃"[j]);
  });
  text({hu: "Áramfázorok – a függőleges vetület a pillanatérték", en: "Current phasors – vertical projection = instantaneous value"},
       px, py + 150, {size: 13, color: C.gray, align: "center"});
  text("nₛ = 60·f / p = " + fmt(60 * P.f / P.p, 0) + " 1/min", px, 430, {size: 20, align: "center", bold: true});
  text("|B| = " + fmt(B.mag / max(P.Im, 1e-9), 2) + " · B̂", px, 465, {size: 18, align: "center"});
  text(P.loss ? {hu: "lüktető mező – a motor nem indul", en: "pulsating field – a motor cannot start"}
              : {hu: "forgó mező, állandó nagyságú", en: "rotating field of constant size"},
       px, 500, {size: 15, align: "center", color: P.loss ? C.red : C.green});

  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Szinkron fordulatszám nₛ", en: "Synchronous speed nₛ"}, 60 * P.f / P.p, "1/min");
  show({hu: "Eredő mező |B| / B̂", en: "Resultant field |B| / B̂"}, B.mag / max(P.Im, 1e-9), "");
  show({hu: "A mező szöge (villamos)", en: "Field angle (electrical)"}, todeg(B.angle), "°");
  for (let j = 0; j < 3; j++) show("i" + "₁₂₃"[j], i[j], "A");

  for (let j = 0; j < 3; j++) plot("i" + "₁₂₃"[j], i[j], {unit: "A", color: PH[j], group: "i"});
  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "|B| / B̂", en: "|B| / B̂"}, B.mag / max(P.Im, 1e-9), {color: C.red, min: 0, max: 2});
});
